mapper.select:
select telemetry_code
from processed_telemetry_filter_selection
where task_id = #{taskId} and device_satellite_id = #{deviceSatelliteId}
  and selection_type = #{selectionType} and target_id = #{targetId}
  and is_deleted = 0

mapper.delete:
delete from processed_telemetry_filter_selection
where task_id = #{taskId} and target_id = #{targetId}
  and selection_type in (3, 4)
